<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'
import { RouterLink } from 'vue-router'
import { supabase } from '../lib/supabase'
import { auth } from '../stores/auth'
import type { Character } from '../lib/types'
const characters = ref<Character[]>([]); const loading = ref(true); const error = ref(''); const deleting = ref<Character | null>(null)
const limit = computed(() => auth.plan?.character_limit ?? 0); const overLimit = computed(() => characters.value.length > limit.value)
async function load() { loading.value = true; const { data, error: queryError } = await supabase.from('characters').select('*').order('name'); if (queryError) error.value = 'Your characters could not be loaded.'; characters.value = data || []; loading.value = false }
function health(character: Character) { return `${character.health ?? 0}/${character.max_health ?? 0}` }
async function remove() { if (!deleting.value) return; const { error: deleteError } = await supabase.from('characters').delete().eq('id', deleting.value.id); if (deleteError) error.value = 'That character could not be deleted.'; else { characters.value = characters.value.filter(item => item.id !== deleting.value?.id); deleting.value = null } }
onMounted(() => { void load() })
</script>
<template><section class="page"><div class="page-heading"><div><div class="eyebrow">Your active roster</div><h2>Characters <span class="count-pill">{{ characters.length }} / {{ limit }}</span></h2><p class="muted">The heroes who carry your story forward.</p></div><RouterLink class="primary" :class="{ disabled: characters.length >= limit }" :to="characters.length >= limit ? '/plans' : '/characters/new'">＋ Create new character</RouterLink></div><div v-if="error" class="form-error">{{ error }}</div><div v-if="overLimit" class="warning">Your plan is over its current character limit. <RouterLink to="/plans">Upgrade your plan</RouterLink> to create another hero.</div><div v-if="loading" class="empty"><p class="muted">Loading your chronicles…</p></div><div v-else-if="!characters.length" class="empty"><div class="empty-glyph">✦</div><h3>No characters yet</h3><p>Create your first hero and give them a place in the chronicles.</p><RouterLink class="primary" to="/characters/new">Create your first hero</RouterLink></div><div v-else class="character-grid"><article v-for="character in characters" :key="character.id" class="character-card"><div class="card-top"><span class="level">LVL {{ character.level ?? 0 }}</span><span class="card-menu">✧</span></div><div class="avatar">{{ character.name.charAt(0) }}</div><h3>{{ character.name }}</h3><p class="species">{{ character.species || 'Unknown' }} <span>·</span> {{ character.role || 'Adventurer' }}</p><div class="health-row"><span>Vitality</span><strong>{{ health(character) }}</strong></div><div class="health-track"><i :style="{ width: `${Math.min(100, (character.health ?? 0) / Math.max(1, character.max_health ?? 0) * 100)}%` }"></i></div><div class="card-actions"><RouterLink :to="`/characters/${character.id}?tab=overview`">View</RouterLink><RouterLink :to="`/characters/${character.id}/edit`">Edit</RouterLink><button class="danger-text" @click="deleting = character">Delete</button></div></article></div><div v-if="deleting" class="modal-backdrop" @click.self="deleting = null"><div class="modal"><div class="danger-icon">!</div><div class="eyebrow">A permanent choice</div><h2>Delete {{ deleting.name }}?</h2><p class="muted">Their attributes, equipment, and journal will be deleted too.</p><div class="modal-actions"><button class="outline" @click="deleting = null">Keep character</button><button class="danger full" @click="remove">Delete character</button></div></div></div></section></template>
